package com.ddarungflow.controller; import com.ddarungflow.dto.StationRhythmDtos; import com.ddarungflow.station.StationRhythmService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/stations") public class StationRhythmController { private final StationRhythmService service; public StationRhythmController(StationRhythmService service){this.service=service;} @GetMapping("/{stationId}/rhythm") public StationRhythmDtos.Response get(@PathVariable String stationId){return service.find(stationId);} @ExceptionHandler(StationRhythmService.NotFound.class) ResponseEntity<StationRhythmDtos.ErrorResponse> missing(){return ResponseEntity.status(HttpStatus.NOT_FOUND).body(new StationRhythmDtos.ErrorResponse("RHYTHM_NOT_AVAILABLE","대여소 패턴을 찾을 수 없습니다."));} }
